cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Specialized cooperative tiled Conv2d:
// NCHW float32, Cin=3, K=11x11, stride=4, pad=2, dilation=1.
// Each CTA computes an 11x28 spatial tile for 32 output channels of one batch.
// Each thread reuses one weight vector across four adjacent output columns.
__device__ __forceinline__ void conv2d_alexnet_accum4(
    const float4 wv, const float xv,
    float& acc0, float& acc1, float& acc2, float& acc3) {
  acc0 += xv * wv.x;
  acc1 += xv * wv.y;
  acc2 += xv * wv.z;
  acc3 += xv * wv.w;
}
template <typename T>
__global__ void __launch_bounds__(616, 1) conv2d_alexnet_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int OC, int H, int Win,
    int Hout, int Wout)
{
  constexpr int Threads = 616;
  constexpr int TOH = 11;
  constexpr int TOW = 28;
  constexpr int OCC = 32;
  constexpr int CIN = 3;
  constexpr int K = 11;
  constexpr int STRIDE = 4;
  constexpr int PAD = 2;
  constexpr int IHT = (TOH - 1) * STRIDE + K;  // 51
  constexpr int IWT = (TOW - 1) * STRIDE + K;  // 119
  constexpr int IWP = ((IWT + 3) / 4) * 4;     // 120, 16B-aligned rows
  constexpr int SX_SIZE = CIN * IHT * IWP;     // 18360
  constexpr int SW_SIZE = OCC * CIN * K * K;   // 11616
  const int tid = threadIdx.x;
  const int oc_chunks = (OC + OCC - 1) / OCC;
  const int n = blockIdx.z / oc_chunks;
  const int oc_chunk = blockIdx.z - n * oc_chunks;
  const int oc0 = oc_chunk * OCC;
  const int oh0 = blockIdx.y * TOH;
  const int ow0 = blockIdx.x * TOW;
  const int base_ih = oh0 * STRIDE - PAD;
  const int base_iw = ow0 * STRIDE - PAD;
  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(N, Int<CIN>{}, H, Win),
      make_stride((int64_t)CIN * H * Win, (int64_t)H * Win, (int64_t)Win, Int<1>{}));
  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, Int<CIN>{}, Int<K>{}, Int<K>{}),
      make_stride((int64_t)CIN * K * K, (int64_t)K * K, (int64_t)K, Int<1>{}));
  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(N, OC, Hout, Wout),
      make_stride((int64_t)OC * Hout * Wout, (int64_t)Hout * Wout, (int64_t)Wout, Int<1>{}));
  extern __shared__ __align__(16) T smem_raw[];
  T* sW_raw = smem_raw;
  T* sX_raw = smem_raw + SW_SIZE;
  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Int<CIN>{}, Int<IHT>{}, Int<IWP>{}),
      make_stride(Int<IHT * IWP>{}, Int<IWP>{}, Int<1>{}));
  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CIN>{}, Int<K>{}, Int<K>{}, Int<OCC>{}),
      make_stride(Int<K * K * OCC>{}, Int<K * OCC>{}, Int<OCC>{}, Int<1>{}));
  for (int idx = tid; idx < SW_SIZE; idx += Threads) {
    int c = idx / (K * K * OCC);
    int rem = idx - c * (K * K * OCC);
    int kh = rem / (K * OCC);
    rem -= kh * (K * OCC);
    int kw = rem / OCC;
    int oc_l = rem - kw * OCC;
    int oc_g = oc0 + oc_l;
    T v = T(0);
    if (oc_g < OC) {
      v = mW(oc_g, c, kh, kw);
    }
    sW(c, kh, kw, oc_l) = v;
  }
  for (int idx = tid; idx < SX_SIZE; idx += Threads) {
    int c = idx / (IHT * IWP);
    int rem = idx - c * (IHT * IWP);
    int ih = rem / IWP;
    int iw = rem - ih * IWP;
    T v = T(0);
    if (iw < IWT) {
      int gih = base_ih + ih;
      int giw = base_iw + iw;
      if ((unsigned)gih < (unsigned)H && (unsigned)giw < (unsigned)Win) {
        v = mX(n, c, gih, giw);
      }
    }
    sX(c, ih, iw) = v;
  }
