  const int sp = tid % SPATIAL_QUADS;              // 0..76 spatial quads
  const int oc_quad = tid / SPATIAL_QUADS;         // 0..7
  const int dy = sp / (TOW / 4);                   // 0..10
  const int dx = (sp % (TOW / 4)) * 4;             // 0,4,...,24
  const int oh = oh0 + dy;
  const int ow = ow0 + dx;
  const int ly = dy * STRIDE;
  const int lx = dx * STRIDE;
  const int oc_l0 = oc_quad * 4;               // 0,4,...,28
  float acc0 = 0.0f;
  float acc1 = 0.0f;
  float acc2 = 0.0f;
  float acc3 = 0.0f;
  float acc4 = 0.0f;
  float acc5 = 0.0f;
  float acc6 = 0.0f;
  float acc7 = 0.0f;
  float acc8 = 0.0f;
  float acc9 = 0.0f;
  float acc10 = 0.0f;
  float acc11 = 0.0f;
  float acc12 = 0.0f;
  float acc13 = 0.0f;
  float acc14 = 0.0f;
  float acc15 = 0.0f;
  const int oc_g0 = oc0 + oc_l0;
  const int oc_g1 = oc0 + oc_l0 + 1;
  const int oc_g2 = oc0 + oc_l0 + 2;
  const int oc_g3 = oc0 + oc_l0 + 3;
  if (B != nullptr) {
    if (oc_g0 < OC) { acc0 = (float)B[oc_g0]; acc4 = acc0; acc8 = acc0; acc12 = acc0; }
    if (oc_g1 < OC) { acc1 = (float)B[oc_g1]; acc5 = acc1; acc9 = acc1; acc13 = acc1; }
    if (oc_g2 < OC) { acc2 = (float)B[oc_g2]; acc6 = acc2; acc10 = acc2; acc14 = acc2; }
    if (oc_g3 < OC) { acc3 = (float)B[oc_g3]; acc7 = acc3; acc11 = acc3; acc15 = acc3; }
  }
  #pragma unroll
  for (int c = 0; c < CIN; ++c) {
    #pragma unroll
    for (int kh = 0; kh < K; ++kh) {
      // 24 consecutive input activations starting at lx cover all four
      // output columns (stride-4 offsets 0,4,8,12) for every kernel tap.
      __align__(16) float xw[24];
      *reinterpret_cast<float4*>(&xw[0]) =
          *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx));
      *reinterpret_cast<float4*>(&xw[4]) =
          *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx + 4));
      *reinterpret_cast<float4*>(&xw[8]) =
          *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx + 8));
      *reinterpret_cast<float4*>(&xw[12]) =
          *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx + 12));
      *reinterpret_cast<float4*>(&xw[16]) =
          *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx + 16));
      *reinterpret_cast<float4*>(&xw[20]) =
          *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx + 20));
      #pragma unroll
      for (int kw = 0; kw < K; ++kw) {
        const float4 wv = *reinterpret_cast<const float4*>(&sW(c, kh, kw, oc_l0));
        conv2d_alexnet_accum4(wv, xw[kw], acc0, acc1, acc2, acc3);
        conv2d_alexnet_accum4(wv, xw[kw + 4], acc4, acc5, acc6, acc7);
        conv2d_alexnet_accum4(wv, xw[kw + 8], acc8, acc9, acc10, acc11);
        conv2d_alexnet_accum4(wv, xw[kw + 12], acc12, acc13, acc14, acc15);
      }
    }
  }
  if (oh < Hout) {
    if (ow < Wout) {
      if (oc_g0 < OC) {
        mY(n, oc_g0, oh, ow) = (T)acc0;
      }
      if (oc_g1 < OC) {
        mY(n, oc_g1, oh, ow) = (T)acc1;
      }
      if (oc_g2 < OC) {
        mY(n, oc_g2, oh, ow) = (T)acc2;
      }
      if (oc_g3 < OC) {
        mY(n, oc_g3, oh, ow) = (T)acc3;
      }
    }
    if (ow + 1 < Wout) {
      if (oc_g0 < OC) {
        mY(n, oc_g0, oh, ow + 1) = (T)acc4;
      }
      if (oc_g1 < OC) {
        mY(n, oc_g1, oh, ow + 1) = (T)acc5;
      }
      if (oc_g2 < OC) {
        mY(n, oc_g2, oh, ow + 1) = (T)acc6;
      }
      if (oc_g3 < OC) {
        mY(n, oc_g3, oh, ow + 1) = (T)acc7;
      }
    }
    if (ow + 2 < Wout) {
      if (oc_g0 < OC) {
        mY(n, oc_g0, oh, ow + 2) = (T)acc8;
      }
      if (oc_g1 < OC) {
        mY(n, oc_g1, oh, ow + 2) = (T)acc9;
      }
      if (oc_g2 < OC) {
        mY(n, oc_g2, oh, ow + 2) = (T)acc10;
      }
      if (oc_g3 < OC) {
        mY(n, oc_g3, oh, ow + 2) = (T)acc11;
      }
    }
    if (ow + 3 < Wout) {
      if (oc_g0 < OC) {
        mY(n, oc_g0, oh, ow + 3) = (T)acc12;
      }
      if (oc_g1 < OC) {
        mY(n, oc_g1, oh, ow + 3) = (T)acc13;
      }
