torch::Tensor conv2d_alexnet_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda() && b.is_cuda(), "x, w, b must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  TORCH_CHECK(b.scalar_type() == at::kFloat, "b must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be NCHW");
  TORCH_CHECK(w.dim() == 4, "w must be [OC,3,11,11]");
  TORCH_CHECK(b.dim() == 1, "b must be [OC]");
  const int64_t N = x.size(0);
  const int64_t CIN = x.size(1);
  const int64_t H = x.size(2);
  const int64_t Win = x.size(3);
  const int64_t OC = w.size(0);
  TORCH_CHECK(CIN == 3, "This kernel expects 3 input channels");
  TORCH_CHECK(w.size(1) == 3 && w.size(2) == 11 && w.size(3) == 11,
              "w must be [OC,3,11,11]");
  TORCH_CHECK(b.size(0) == OC, "bias must match out_channels");
  constexpr int64_t STRIDE = 4;
  constexpr int64_t PAD = 2;
  constexpr int64_t K = 11;
  const int64_t Hout = (H + 2 * PAD - K) / STRIDE + 1;
  const int64_t Wout = (Win + 2 * PAD - K) / STRIDE + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output spatial size");
  TORCH_CHECK(N <= INT_MAX && OC <= INT_MAX && H <= INT_MAX && Win <= INT_MAX &&
              Hout <= INT_MAX && Wout <= INT_MAX, "tensor dims too large");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  auto b_c = b.contiguous();
  auto y = torch::empty({N, OC, Hout, Wout}, x_c.options());
  constexpr int Threads = 352;
  constexpr int TOH = 11;
  constexpr int TOW = 8;
  constexpr int OCC = 32;
  constexpr int SM_CIN = 3;
  constexpr int SM_K = 11;
  constexpr int SM_IHT = (TOH - 1) * 4 + SM_K;
  constexpr int SM_IWT = (TOW - 1) * 4 + SM_K;
  constexpr int SM_IWP = ((SM_IWT + 3) / 4) * 4;
  constexpr int SX_SIZE = SM_CIN * SM_IHT * SM_IWP;
  constexpr int SW_SIZE = OCC * SM_CIN * SM_K * SM_K;
  const size_t smem_bytes = (size_t)(SX_SIZE + SW_SIZE) * sizeof(float);
  cudaError_t attr_err = cudaFuncSetAttribute(
      (const void*)conv2d_alexnet_kernel<float>,
      cudaFuncAttributeMaxDynamicSharedMemorySize,
      (int)smem_bytes);
  TORCH_CHECK(attr_err == cudaSuccess, "failed to set max dynamic shared memory: ",
              cudaGetErrorString(attr_err));
  const int64_t oc_chunks = (OC + OCC - 1) / OCC;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)((Wout + TOW - 1) / TOW),
      (unsigned)((Hout + TOH - 1) / TOH),
      (unsigned)(N * oc_chunks));
  TORCH_CHECK(grid.z <= 65535, "grid.z exceeds CUDA limit for this kernel");
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_alexnet_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)N, (int)OC, (int)H, (int)Win,
      (int)Hout, (int)Wout);
  cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_alexnet_kernel launch failed: ",
              cudaGetErrorString(err));
  return y;
}
